async function postTitles(blog) {
  try {
    const response = await fetch(blog + '/search-index.json', {signal: AbortSignal.timeout(2500)});
    if (response.ok) {
      const index = await response.json();
      return new Map(index.map(([title, , , path]) => [path, title]));
    }
  } catch {
    // A temporary index error must not prevent moderation.
  }
  return new Map();
}

function render(comment) {
    const item = document.createElement('li');
    const content = document.createElement('div');
    const meta = document.createElement('div');
    meta.className = 'comment-meta';
    const name = document.createElement('strong');
    name.textContent = comment.nickname;
    const time = document.createElement('time');
    time.dateTime = comment.created_at;
    time.textContent = date.format(new Date(comment.created_at));
    const body = document.createElement('p');
    body.textContent = comment.body;
    const link = document.createElement('a');
    link.className = 'comment-post';
    link.href = comment.postUrl;
    const icon = document.createElement('span');
    icon.setAttribute('aria-hidden', 'true');
    icon.textContent = '▤';
    const title = document.createElement('span');
    title.textContent = comment.postTitle;
    link.append(icon, title);
    const remove = document.createElement('button');
    remove.className = 'record-policy';
    remove.type = 'button';
    remove.textContent = '삭제';
    remove.setAttribute('aria-label', comment.nickname + '님의 댓글 삭제');
    remove.addEventListener('click', () => removeComment(comment.id, remove));
    meta.append(name, time);
    content.append(meta, body, link);
    item.append(content, remove);
    return item;
  }
